"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 step 3, option C (chosen by the author, 2026-11-19): the conditional version. The decision changes only where
the label and the sound disagree. Exploratory, local, no API; dev for evaluation; test and replication untouched.

Why: the step-2 read-out (scripts/p1v4_readout.py, setting "ears") follows hearing on the hard subset, but it costs
the H-S and H-E floors (0.99 -> 0.90, 0.98 -> 0.94). Every new floor miss is a case where the label is right and the
sound real: it answers "phone heard" and ignores the words. A version that keeps the old decision wherever label
and sound agree should keep the floors and the listening gains.

Design, fixed in the log before running:
- Ears probe: logistic regression on the pooled audio tokens (mean and max, 2,048 numbers; the read-out's "ears";
  text edits do not change them), target "a real phone, doorbell or knock clip overlaps the 8 s window". Trained on
  every train window; weight decay from {1e-4, 1e-3, 1e-2, 1e-1} by log loss on the 20% unit-grouped holdout of
  step 2, then refitted on all of train. "Heard" = probe probability >= 0.5.
- Label side: "the label says yes" = the highest confidence of the phone, doorbell or knock detections that overlap
  the window in the input text is >= 0.9 (the old head follows labels from about 0.9 on, trust curves 2026-11-19).
- Routing per window: if "heard" and "the label says yes" agree, both questions (S, R) are decided by the old head
  at its dev thresholds (0.286, 0.049); if they disagree, by the step-2 read-out at its dev thresholds (0.742,
  0.615). No new threshold is tuned. Score form: sigmoid(logit p - logit threshold) of the routed head, so the
  thresholds (0.5, 0.5) reproduce the routing exactly and the plan's scoring and decision-table code apply as is.
- Dev inputs: natural, false labels at 0.9, labels removed (as step 2). Same features as step 2 (no new forward pass).
- Criteria, fixed now:
  1. hard subset (ring or knock labels 0.5-0.9 at R-hear points; 24 real, 51 false): real labels followed >= 18,
     false labels followed <= 5;
  2. with false labels at 0.9, the five-part mean drops by at most 2 points;
  3. every floor kind (D, Dk, H-E, H-S, barge, quiet) at most 2 points below the old head's on natural dev;
  4. the plan's decision table (scripts/p1v4_test_report.py, unchanged) run on dev lands in row 1 or 2.
- Selection, fixed now: if all four hold, the conditional version becomes the candidate main system (it enters the
  main comparison only by a logged amendment and the review before the freeze). Otherwise the numbers of all three
  candidates go back to the user; no automatic choice. (The read-out alone fails 3; the combination fails 1.)
- Also reported: share of questions routed to the read-out (by part and input); ears-probe AUC (train holdout, dev
  windows, hard subset); parts, floors, audio-decisive part; drop with labels removed; hard-subset decision AUC;
  intervals against the old head, the read-out, the combination and each Gemini reader's current dev choice.
usage (repo root):
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_conditional.py probe
  .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_conditional.py eval
Outputs: data/p1v4/runs/readout/ears_probe.npz, ears_probe_log.json, scores_dev_conditional.json;
results/main_v04/conditional_dev.json, results/main_v04/decision_dev_dryrun_conditional.json.
"""
import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_score as S  # noqa: E402

OUT = RO.OUT
LABEL_TRUST = 0.9
EARS_CUT = 0.5
FLOOR_SLACK = 0.02
CONDS = ("natural", "false09", "removed")


def fit_probe():
    from sklearn.metrics import roc_auc_score
    D.gpu_guard()
    z = np.load(f"{OUT}/feats_train_train.npz")
    X = z["ears"].astype(np.float32)
    y = z["real"].astype(np.float32)
    units = z["units"]
    rng = np.random.default_rng(RO.SEED)
    uniq = np.unique(units)
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    mu, sd = X.mean(0), X.std(0) + 1e-6
    X = ((X - mu) / sd).astype(np.float32)
    log, best = {"base_rate_train": float(y.mean()), "n_windows": int(len(y))}, None
    for wd in RO.WDS:
        lin = RO.train_logreg(X[~hold], y[~hold], wd)
        p = np.clip(RO.predict(lin, X[hold]), 1e-7, 1 - 1e-7)
        yy = y[hold]
        ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
        auc = float(roc_auc_score(yy, p))
        log[f"wd {wd}"] = {"holdout_log_loss": ll, "holdout_auc": auc, "holdout_acc": float(((p >= EARS_CUT) == yy).mean())}
        print(f"ears probe wd {wd}: holdout log loss {ll:.4f}, AUC {auc:.4f}, accuracy at 0.5 "
              f"{log[f'wd {wd}']['holdout_acc']:.4f} (n {int(hold.sum())})", flush=True)
        if best is None or ll < best[0]:
            best = (ll, wd)
    lin = RO.train_logreg(X, y, best[1])
    log["chosen_wd"] = best[1]
    np.savez(f"{OUT}/ears_probe.npz", mu=mu, sd=sd, w=lin.weight.detach().cpu().numpy()[0],
             b=float(lin.bias.detach().cpu().numpy()[0]), wd=best[1])
    json.dump(log, open(f"{OUT}/ears_probe_log.json", "w"), indent=1)
    print(f"ears probe: chosen wd {best[1]}, refitted on {len(y)} windows (base rate {y.mean():.3f})", flush=True)


def probe_p(ears, pr):
    lg = ((ears.astype(np.float32) - pr["mu"]) / pr["sd"]) @ pr["w"] + float(pr["b"])
    return 1 / (1 + np.exp(-lg))


def logit(p):
    p = np.clip(p, 1e-7, 1 - 1e-7)
    return np.log(p) - np.log1p(-p)


def conditional(z, ro, pr, th_old, th_new):
    """Scores {(unit, version, k): {"S": s, "R": s}} of the routed head as sigmoid(logit p - logit threshold); the
    routing per window (True = read-out) and the ears probe's probability per window."""
    old = RO.scores_of(z, None, ro)
    new = RO.scores_of(z, "ears", ro)
    pe = probe_p(z["ears"], pr)
    heard = pe >= EARS_CUT
    says = z["conf"] >= LABEL_TRUST
    route = heard != says
    sc = {}
    for w, idv in enumerate(z["ids"]):
        u, v, k = idv.split("|")
        key = (u, v, int(k))
        src, th = (new, th_new) if route[w] else (old, th_old)
        sc[key] = {q: float(1 / (1 + np.exp(-(logit(p) - logit(th[q]))))) for q, p in src.get(key, {}).items()}
    return sc, route, pe


def eval_():
    from sklearn.metrics import roc_auc_score
    import p1v4_combo_pilot as CP
    import p1v4_context as C
    import p1v4_test_report as TR
    import p1v4_trust_curves as TC
    rows = D.load_rows("dev")
    groups = S.load_groups("dev")
    pts = TC.r_hear_points(rows, C.Context("dev"))
    hard = {q["key"]: q["real"] for q in pts if q["conf"] is not None and 0.5 <= q["conf"] < 0.9}
    ro = RO.load_readouts()
    pz = np.load(f"{OUT}/ears_probe.npz")
    pr = {k: pz[k] for k in pz.files}
    step2 = json.load(open("results/main_v04/readout_dev.json"))
    rep = json.load(open("results/main_v04/dev_report.json"))["systems"]
    th_old = {"S": rep["L1"]["operating_point"]["th_s"], "R": rep["L1"]["operating_point"]["th_r"]}
    th_new = {"S": step2["settings"]["ears"]["th_s"], "R": step2["settings"]["ears"]["th_r"]}
    res = {"thresholds": {"old head": th_old, "read-out": th_new}, "inputs": {}}
    tables = {}
    for c in CONDS:
        z = dict(np.load(f"{OUT}/feats_dev_{c}.npz"))
        sc, route, pe = conditional(z, ro, pr, th_old, th_new)
        dec = S.decide(sc, 0.5, 0.5)
        T = S.unit_table(rows, dec, groups)
        m = S.metrics(T)
        parts = z["parts"]
        share = {"all windows": float(route.mean())}
        share.update({p: float(route[parts == p].mean()) for p in sorted(set(parts.tolist()))})
        out = {"primary": m["primary"], "parts": m["parts"], "audio": m["audio"], "floors": m["floors"],
               "mid_confidence_follow": CP.mid_follow(pts, dec), "routed_to_readout": share}
        if c == "natural":
            tables["conditional"] = T
            keys = list(hard)
            yh = np.array([hard[k] for k in keys])
            out["hard_subset_decision_auc"] = float(roc_auc_score(yh, np.array([1 - sc[k]["R"] for k in keys])))
            real = z["real"].astype(int)
            win = {tuple([i.split("|")[0], i.split("|")[1], int(i.split("|")[2])]): w for w, i in enumerate(z["ids"])}
            hw = np.array([win[k] for k in keys])
            res["ears_probe_dev"] = {"auc_all_windows": float(roc_auc_score(real, pe)),
                                     "acc_all_windows": float(((pe >= EARS_CUT) == real).mean()),
                                     "auc_hard_subset": float(roc_auc_score(yh, pe[hw])),
                                     "hard_subset_routed": {"real": int(route[hw][yh == 1].sum()),
                                                            "false": int(route[hw][yh == 0].sum())}}
            json.dump({f"{u}|{v}|{k}": x for (u, v, k), x in sc.items()},
                      open(f"{OUT}/scores_dev_conditional.json", "w"))
        res["inputs"][c] = out
    nat = res["inputs"]["natural"]
    res["drop_false09"] = nat["primary"] - res["inputs"]["false09"]["primary"]
    res["drop_removed"] = nat["primary"] - res["inputs"]["removed"]["primary"]

    old_floors = step2["settings"]["old head"]["natural"]["floors"]
    base = TR.dev_manifest

    def manifest():
        m = base()
        m[TR.OURS] = {"kind": "score", "path": f"{OUT}/scores_dev_conditional.json", "th_s": 0.5, "th_r": 0.5}
        return m
    TR.dev_manifest = manifest
    dry = TR.run("dev", "results/main_v04/decision_dev_dryrun_conditional.json")
    TR.dev_manifest = base
    mf = nat["mid_confidence_follow"]
    res["criteria"] = {
        "1 hard subset (real >= 18/24, false <= 5/51)": mf["real"][0] >= 18 and mf["false"][0] <= 5,
        "2 drop under false labels at 0.9 <= 2 points": res["drop_false09"] <= 0.02,
        "3 every floor at most 2 points below the old head": all(nat["floors"][k] >= old_floors[k] - FLOOR_SLACK
                                                                  for k in old_floors),
        "4 decision-table dry run on dev in row 1 or 2": dry["row"] in ("1 M-listen", "2 M-data")}
    res["decision_table_row"] = dry["row"]
    res["selection"] = ("conditional version is the candidate main system" if all(res["criteria"].values())
                        else "not all criteria hold: numbers of all three candidates go back to the user")

    others = {"old head": S.unit_table(rows, S.decide(RO.scores_of(dict(np.load(f"{OUT}/feats_dev_natural.npz")),
                                                                    None, ro), th_old["S"], th_old["R"]), groups)}
    rsc = CP.keyed(json.load(open(f"{OUT}/scores_dev_readout.json")))
    others["read-out"] = S.unit_table(rows, S.decide(rsc, th_new["S"], th_new["R"]), groups)
    csc = CP.keyed(json.load(open(f"{OUT}/scores_dev_combination.json")))
    op = S.operating_point(rows, csc)
    others["combination"] = S.unit_table(rows, S.decide(csc, op["th_s"], op["th_r"]), groups)
    for n, sd in (("B2-fast", "b2fast"), ("B2-strong", "b2strong")):
        op = rep[n]["operating_point"]
        bsc = CP.keyed(json.load(open(f"{RO.R}/api/{sd}/scores_dev_{op['setting']}.json")))
        others[f"{n} ({op['setting']})"] = S.unit_table(rows, S.decide(bsc, op["th_s"], op["th_r"]), groups)
    res["vs"] = {n: {w: S.interval(tables["conditional"], T, w) for w in ("primary", "audio", "part:r_hear")}
                 for n, T in others.items()}
    json.dump(res, open("results/main_v04/conditional_dev.json", "w"), indent=1)

    print("ears probe on dev:", json.dumps(res["ears_probe_dev"]))
    for c, x in res["inputs"].items():
        print(f"{c:8s} mean {x['primary']:.3f} audio {x['audio']:.3f} parts "
              + " ".join(f"{p}:{x['parts'][p]:.3f}" for p in S.PARTS)
              + f" | mid follow real {x['mid_confidence_follow']['real'][0]}/24 false "
                f"{x['mid_confidence_follow']['false'][0]}/51 | routed {x['routed_to_readout']['all windows']:.3f}")
        print("         floors " + " ".join(f"{k}:{v:.2f}" for k, v in x["floors"].items())
              + " | routed by part " + " ".join(f"{p}:{v:.3f}" for p, v in x["routed_to_readout"].items()
                                                if p != "all windows"))
    print(f"hard AUC {nat['hard_subset_decision_auc']:.3f} | drop false@0.9 {res['drop_false09']:+.3f} | "
          f"drop removed {res['drop_removed']:+.3f}")
    print("criteria:", json.dumps(res["criteria"]))
    print("selection:", res["selection"])
    for n, v in res["vs"].items():
        print(f"conditional - {n}: " + "; ".join(f"{w} {v[w]['point']:+.3f} [{v[w]['ci95'][0]:+.3f}, "
                                                  f"{v[w]['ci95'][1]:+.3f}]" for w in ("primary", "audio", "part:r_hear")))


if __name__ == "__main__":
    {"probe": fit_probe, "eval": eval_}[sys.argv[1]]()
